{
  "title": "HCV adherence and transmission game",
  "perWatchSecond": 3.0,
  "levels": [
    {
      "kind": "hook",
      "title": "Quitters transmission",
      "goal": "Show how reducing transmission from quitters lowers their numbers.",
      "control": {
        "parameter": "beta3",
        "label": "Quitter transmission rate",
        "lowEnd": "0.01",
        "highEnd": "0.1"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if the quit‑treatment transmission rate β₃ is halved?",
        "parameter": "beta3",
        "value": 0.025
      },
      "difference": {
        "compartment": "cq",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "lower",
        "by": 0.0001
      },
      "effect": "Halving β₃ reduces the quitters proportion at year 200 by more than 1e-4.",
      "prediction": {
        "prompt": "Predict the quitters proportion when β₃ is halved.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Higher transmissibility of quitters",
        "quote": "We assumed that β₂ < β₃, since quitting treatment before reaching sustained viral response (SVR) increases HCV viral load, leading to higher transmissibility."
      },
      "carryForward": "Next, see how changing the quitting rate affects the on‑treatment group."
    },
    {
      "kind": "background",
      "title": "Quitting rate impact",
      "goal": "Explore how increasing the quitting rate changes the on‑treatment population.",
      "control": {
        "parameter": "delta",
        "label": "Treatment quitting rate",
        "lowEnd": "0.1",
        "highEnd": "1.0"
      },
      "watch": "c",
      "whatIf": {
        "prompt": "What if the quitting rate δ is doubled?",
        "parameter": "delta",
        "value": 1.2
      },
      "difference": {
        "compartment": "c",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "lower",
        "by": 0.00002
      },
      "effect": "Doubling δ cuts the on‑treatment proportion at year 200 by more than 2e-5.",
      "prediction": {
        "prompt": "Predict the on‑treatment proportion when δ doubles.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Quitting increases infectivity",
        "quote": "We assumed that β₂ < β₃, since quitting treatment before reaching sustained viral response (SVR) increases HCV viral load, leading to higher transmissibility."
      },
      "carryForward": "Finally, examine how higher adherence influences acute infection."
    },
    {
      "kind": "result",
      "title": "Adherence threshold",
      "goal": "Demonstrate that higher adherence reduces acute infection.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence proportion",
        "lowEnd": "0.3",
        "highEnd": "0.9"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if adherence θ is increased to 70%?",
        "parameter": "theta",
        "value": 0.7
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "lower",
        "by": 0.00005
      },
      "effect": "Increasing θ to 70% lowers the acute infection proportion at year 200 by more than 5e-5.",
      "prediction": {
        "prompt": "Predict the acute infection level when θ rises to 70%.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Adherence threshold",
        "quote": "The study demonstrated that an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "You have completed the game."
    }
  ],
  "limits": [
    "All claims must hold under ±10% parameter variations.",
    "Each level runs for 200 years, fitting the speed constraint."
  ]
}
